404	    /**
405	     * Build a {@code customerCode} formatted {@code '<REGION>-<HASH8>'} where REGION is the region
406	     * code derived from the owner's postcode (see {@link Region#regionForPostcode(String)}) and
407	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the concatenation of
408	     * the owner's normalized telephone and {@code lastName}. The telephone is already normalized by
409	     * {@link #saveOwner(Owner)} before this runs. The {@code '<REGION>-<HASH8>'} layout is read back
410	     * by {@link Region#regionOfCustomerCode(String)}; keep the two in sync.
411	     */
412	    private String generateCustomerCode(Owner owner) {
413	        String region = Region.regionForPostcode(owner.getPostcode());
414	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
415	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
416	        String hash8 = Sha256Hex.upperHex(telephone + lastName, 8);
417	        return deduplicateCustomerCode(owner, region + "-" + hash8);
418	    }
