420	    /**
421	     * Returns {@code base} unchanged when no other owner already holds it; otherwise appends
422	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result unique among the
423	     * existing owners' {@code customerCode}s. The {@code owner} being saved is excluded from the
424	     * comparison so re-saving it does not treat its own code as a collision.
425	     */
426	    private String deduplicateCustomerCode(Owner owner, String base) {
427	        Set<String> taken = new HashSet<>();
428	        for (Owner existing : ownerRepository.findAll()) {
429	            if (!existing.getId().equals(owner.getId()) && existing.getCustomerCode() != null) {
430	                taken.add(existing.getCustomerCode());
431	            }
432	        }
433	        if (!taken.contains(base)) {
434	            return base;
435	        }
436	        int n = 2;
437	        while (taken.contains(base + "-" + n)) {
438	            n++;
439	        }
440	        return base + "-" + n;
441	    }
