467	    /**
468	     * Rolls {@code date} forward to the next business day. A business day is Monday to Friday that is
469	     * not a listed public holiday; Saturdays, Sundays and public holidays are skipped by advancing
470	     * one day at a time until a business day is reached. Business days are returned unchanged.
471	     */
472	    private static LocalDate rollToBusinessDay(LocalDate date) {
473	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
474	            date = date.plusDays(1);
475	        }
476	        return date;
477	    }
